(()=>{const q=new URLSearchParams(location.search),k=({small_group:'group2',group:'group2',solo:'open_group','1-on-1':'1on1'})[q.get('package')]||q.get('package');if(k&&S.packages[k]){f.ptype.value=S.packages[k].players>1?'group':k;if(S.packages[k].players>1)f.players.value=String(S.packages[k].players);pkgUI();st.textContent=pkgText(k)+'. Fill in your info, then continue.'}})();
(()=>{const q=new URLSearchParams(location.search),p=q.get('program'),w=q.get('type'),t=q.get('t')||q.get('time');if(!p&&!w&&!t)return;
if(p){const c=f.querySelector('[name=programs][value="'+p.replace(/"/g,'')+'"]');if(c){f.querySelectorAll('[name=programs]').forEach(x=>x.checked=x===c);f.program.value=p;f.querySelectorAll('[name=workout_type]').forEach(x=>x.checked=x.value===TYPE_OF[p])}}
const r=w&&f.querySelector('[name=workout_type][value="'+w.replace(/"/g,'')+'"]');if(r){if(p)f.querySelectorAll('[name=workout_type]').forEach(x=>x.checked=false);r.checked=true;ctype=w}
if(t&&!isNaN(Date.parse(t))){const iso=new Date(t).toISOString();picked.set(iso,r?w:wts()[0]);day=new Date(iso).toLocaleDateString('en-CA',{timeZone:tz})}
const n=document.getElementById('picked');st.textContent=t?'Selected '+fd(t,{weekday:'short',month:'short',day:'numeric',hour:'numeric'})+' · '+(w||'')+' · '+(p?progLabel(p):'')+'. Fill in your info, then continue.':''})();

